import * as React from "react";
import { TriangleAlert, X } from "lucide-react";
import { Input } from "@/components/ui/input";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { SheetField } from "@/components/side-sheet/parts";
import { HangingAdd } from "./HangingAdd";
import { Slider } from "@/components/ui/slider";
import {
  formatSpan,
  formatWindow,
} from "@/components/form-layout/TimeWindowSlider";
import { cn } from "@/lib/utils";
/** A stretch of the day, minutes from midnight. */
export interface TimeSpan {
  start: number;
  end: number;
}

/*
  DELIVERY WINDOW & PREFERRED TIME (Pavan, 2026-10-20, after his reference;
  shared by every module's order sheet) —
  ONE day, drawn once, full width. The delivery window is the range on the
  track; each preferred time is a light-blue bar under it, on the same scale,
  with dashed lines up to the track and its two times under its ends. A bar
  is moved by dragging it, sized by dragging an end, and removed with its ✕;
  the + hanging off the box (as a table's add) puts a new one in the
  window's next free stretch.

  Keyboard: a bar takes focus — ← → move it half an hour, Shift + ← → move
  its end, Delete removes it.

  NEVER OVERLAPPING (Pavan, 2026-10-20) — a bar stops at its neighbours,
  whichever way it is dragged or typed; with no free half hour left in the
  window, + says to delete or adjust one first. PRESS A TIME under a bar to
  type its start and end to the minute — the slider and the box are the same
  value.
*/

const DAY = 24 * 60;
const STEP = 30;
/** Every third hour labelled, as the reference. */
const TICKS = [0, 3, 6, 9, 12, 15, 18, 21, 24];
const pct = (m: number) => `${(m / DAY) * 100}%`;
/** `4a`, `1:30p` — the reference's short times. */
const short = (m: number) => {
  const h24 = Math.floor((((m % DAY) + DAY) % DAY) / 60);
  const mm = m % 60;
  const h = h24 % 12 === 0 ? 12 : h24 % 12;
  return `${h}${mm ? `:${String(mm).padStart(2, "0")}` : ""}${h24 < 12 ? "a" : "p"}`;
};
const hhmm = (m: number) =>
  `${String(Math.floor(m / 60)).padStart(2, "0")}:${String(m % 60).padStart(2, "0")}`;
const fromHhmm = (v: string) => {
  const m = v.match(/^(\d{1,2}):(\d{2})$/);
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
};
const tick = (h: number) =>
  h === 0 || h === 24
    ? "12a"
    : h === 12
      ? "12p"
      : h < 12
        ? `${h}a`
        : `${h - 12}p`;

type Drag = {
  i: number;
  mode: "move" | "start" | "end";
  grab: number;
  from: TimeSpan;
};

export function DeliveryWindowTimeline({
  start,
  end,
  onWindowChange,
  preferred,
  onPreferredChange,
  disabled,
  required,
  label = "Delivery window & preferred time",
}: {
  /** The field's label, outside the box — every module says it its own way. */
  label?: string;
  /** The delivery window, minutes from midnight. */
  start: number;
  end: number;
  onWindowChange: (start: number, end: number) => void;
  preferred: TimeSpan[];
  onPreferredChange: (next: TimeSpan[]) => void;
  disabled?: boolean;
  required?: boolean;
}) {
  const scale = React.useRef<HTMLDivElement>(null);
  const [width, setWidth] = React.useState(0);
  React.useLayoutEffect(() => {
    if (!scale.current) return;
    const ro = new ResizeObserver(([e]) => setWidth(e.contentRect.width));
    ro.observe(scale.current);
    return () => ro.disconnect();
  }, []);
  const drag = React.useRef<Drag | null>(null);
  /* THE NEW BAR TAKES FOCUS (DS ui §10f) — so ← → move it at once. */
  const [focusNew, setFocusNew] = React.useState<number | null>(null);
  /** The bar whose times are being typed, and which box opened it. */
  const [edit, setEdit] = React.useState<{
    i: number;
    field: "start" | "end";
  } | null>(null);
  const [full, setFull] = React.useState(false);
  React.useEffect(() => setFull(false), [preferred, start, end]);

  /* THE ROOM A BAR HAS — from its neighbours (or the window) either side. */
  const room = (i: number, at: TimeSpan) => {
    const others = preferred.filter((_, j) => j !== i);
    return {
      lo: Math.max(
        start,
        ...others.filter((q) => q.end <= at.start).map((q) => q.end),
      ),
      hi: Math.min(
        end,
        ...others.filter((q) => q.start >= at.end).map((q) => q.start),
      ),
    };
  };

  const toMin = (clientX: number) => {
    const r = scale.current!.getBoundingClientRect();
    return Math.round((((clientX - r.left) / r.width) * DAY) / STEP) * STEP;
  };
  const clampSpan = (
    i: number,
    at: TimeSpan,
    s: number,
    e: number,
    mode: Drag["mode"],
  ): TimeSpan => {
    const { lo, hi } = room(i, at);
    if (mode === "move") {
      const len = e - s;
      const a = Math.min(Math.max(s, lo), hi - len);
      return { start: a, end: a + len };
    }
    if (mode === "start")
      return { start: Math.min(Math.max(s, lo), e - STEP), end: e };
    return { start: s, end: Math.max(Math.min(e, hi), s + STEP) };
  };
  const setAt = (i: number, p: TimeSpan) =>
    onPreferredChange(preferred.map((x, j) => (j === i ? p : x)));

  const onDown = (e: React.PointerEvent, i: number, mode: Drag["mode"]) => {
    if (disabled) return;
    e.preventDefault();
    e.stopPropagation();
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    drag.current = { i, mode, grab: toMin(e.clientX), from: preferred[i] };
  };
  const onMove = (e: React.PointerEvent) => {
    const d = drag.current;
    if (!d) return;
    const delta = toMin(e.clientX) - d.grab;
    const s = d.mode === "end" ? d.from.start : d.from.start + delta;
    const en = d.mode === "start" ? d.from.end : d.from.end + delta;
    setAt(d.i, clampSpan(d.i, d.from, s, en, d.mode));
  };
  const onUp = () => (drag.current = null);

  const add = () => {
    /* THE FIRST FREE STRETCH OF HALF AN HOUR OR MORE, up to two hours. */
    const taken = [...preferred].sort((a, b) => a.start - b.start);
    let at = start;
    for (const q of [...taken, { start: end, end }]) {
      if (q.start - at >= STEP) {
        setFocusNew(preferred.length);
        onPreferredChange([
          ...preferred,
          { start: at, end: Math.min(q.start, at + 120) },
        ]);
        return;
      }
      at = Math.max(at, q.end);
    }
    setFull(true);
  };
  /* A TYPED PAIR — what's wrong with it, or null when it fits. */
  const problem = (i: number, s: number | null, e: number | null) => {
    if (s === null || e === null) return "Enter both times";
    if (e <= s) return "End after the start";
    if (s < start || e > end)
      return `Inside the delivery window, ${formatWindow(start, end)}`;
    if (preferred.some((q, j) => j !== i && s < q.end && e > q.start))
      return "Overlaps another preferred time";
    return null;
  };
  const onKey = (e: React.KeyboardEvent, i: number) => {
    const p = preferred[i];
    const by =
      e.key === "ArrowRight" ? STEP : e.key === "ArrowLeft" ? -STEP : 0;
    if (by) {
      e.preventDefault();
      setAt(
        i,
        e.shiftKey
          ? clampSpan(i, p, p.start, p.end + by, "end")
          : clampSpan(i, p, p.start + by, p.end + by, "move"),
      );
    } else if (e.key === "Delete" || e.key === "Backspace") {
      e.preventDefault();
      onPreferredChange(preferred.filter((_, j) => j !== i));
    }
  };

  const has = preferred.length > 0;
  const canAdd = !disabled && end - start >= STEP;
  return (
    /* THE LABEL OUTSIDE, as every field's (Pavan, 2026-10-20); the unit in
       the input's own outline; the add hangs off its corner, as a table's. */
    <SheetField label={label} required={required}>
      <div className="flex flex-col">
        <div
          className={cn(
            "flex flex-col gap-2 rounded-md border border-input bg-fp-surface-1b px-4 pt-3 pb-3 transition-[color,box-shadow] focus-within:border-ring focus-within:ring-2 focus-within:ring-ring/50 dark:bg-fp-field-fill",
            canAdd && "rounded-bl-none",
          )}
        >
          <div className="flex min-w-0 items-baseline justify-between gap-3">
            <span className="text-sm whitespace-nowrap tabular-nums text-foreground">
              {formatWindow(start, end)}
            </span>
            <span className="min-w-0 truncate text-xs text-muted-foreground">
              {formatSpan(start, end)}
            </span>
          </div>

          {/* THE SCALE — track, hours, then the preferred bars on the same day. */}
          <div
            ref={scale}
            className={cn("relative", has ? "h-[78px]" : "h-10")}
            onPointerMove={onMove}
            onPointerUp={onUp}
          >
            <Slider
              className="absolute inset-x-0 top-0 h-5 [&_[data-slot=slider-thumb]]:size-5 [&_[data-slot=slider-track]]:h-2.5"
              aria-label="Delivery window"
              min={0}
              max={DAY}
              step={STEP}
              minStepsBetweenThumbs={60 / STEP}
              value={[start, end]}
              disabled={disabled}
              onValueChange={([a, b]) => onWindowChange(a, b)}
            />
            <div
              aria-hidden
              className="absolute inset-x-0 top-6 h-3.5 select-none"
            >
              {TICKS.map((h, i) => (
                <span
                  key={h}
                  className={cn(
                    "absolute top-0 text-xs leading-none tabular-nums text-muted-foreground",
                    i === 0 && "left-0",
                    i === TICKS.length - 1 && "right-0",
                    i > 0 && i < TICKS.length - 1 && "-translate-x-1/2",
                  )}
                  style={
                    i === 0 || i === TICKS.length - 1
                      ? undefined
                      : { left: `${(h / 24) * 100}%` }
                  }
                >
                  {tick(h)}
                </span>
              ))}
            </div>

            {preferred.map((p, i) => {
              /* A NARROW BAR PUTS ITS TIMES OUTSIDE ITS ENDS, so they never meet. */
              const narrow =
                width > 0 && ((p.end - p.start) / DAY) * width < 84;
              /* WHERE TWO BARS MEET, THE TIME IS PRINTED ONCE — by the later bar. */
              const shared = preferred.some(
                (q, j) => j !== i && q.start === p.end,
              );
              return (
                <React.Fragment key={i}>
                  {[p.start, p.end].map((m, k) => (
                    <span
                      key={k}
                      aria-hidden
                      className="absolute top-4 h-7 border-l border-dashed border-muted-foreground/60"
                      style={{ left: pct(m) }}
                    />
                  ))}
                  <div
                    role="group"
                    ref={(el) => {
                      if (el && i === focusNew) {
                        el.focus({ preventScroll: true });
                        setFocusNew(null);
                      }
                    }}
                    autoFocus={i === focusNew}
                    tabIndex={disabled ? -1 : 0}
                    aria-label={`Preferred time ${formatWindow(p.start, p.end)}`}
                    onKeyDown={(e) => !disabled && onKey(e, i)}
                    onPointerDown={(e) => onDown(e, i, "move")}
                    className={cn(
                      "group/bar absolute top-11 h-2.5 rounded-xs bg-fp-lane-blue/30 outline-none focus-visible:ring-2 focus-visible:ring-ring/50",
                      !disabled &&
                        "cursor-grab active:cursor-grabbing hover:bg-fp-lane-blue/45",
                    )}
                    /* 1px of air each side, so two bars that meet stay two. */
                    style={{
                      left: `calc(${pct(p.start)} + 1px)`,
                      width: `calc(${pct(p.end - p.start)} - 2px)`,
                    }}
                  >
                    {!disabled && (
                      <>
                        {/* THE ENDS SIZE IT — a grip wider than the line. */}
                        <span
                          onPointerDown={(e) => onDown(e, i, "start")}
                          className="absolute inset-y-[-4px] -left-1.5 w-3 cursor-ew-resize"
                        />
                        <span
                          onPointerDown={(e) => onDown(e, i, "end")}
                          className="absolute inset-y-[-4px] -right-1.5 w-3 cursor-ew-resize"
                        />
                        <button
                          type="button"
                          aria-label={`Remove preferred time ${formatWindow(p.start, p.end)}`}
                          onPointerDown={(e) => e.stopPropagation()}
                          onClick={() =>
                            onPreferredChange(
                              preferred.filter((_, j) => j !== i),
                            )
                          }
                          className="absolute top-1/2 -right-6 flex size-5 -translate-y-1/2 items-center justify-center rounded-sm text-muted-foreground opacity-0 outline-none transition-opacity group-hover/bar:opacity-100 group-focus-visible/bar:opacity-100 hover:text-foreground focus-visible:opacity-100 focus-visible:ring-2 focus-visible:ring-ring/50"
                        >
                          <X className="size-3.5" />
                        </button>
                      </>
                    )}
                  </div>
                  {/* A SHORT BAR CARRIES ONE LABEL, BOTH TIMES — two would run
                      into each other or into the next bar's. */}
                  <TimeLabel
                    m={p.start}
                    text={
                      narrow && !shared
                        ? `${short(p.start)}–${short(p.end)}`
                        : undefined
                    }
                    open={edit?.i === i && edit.field === "start"}
                    onOpenChange={(o) =>
                      setEdit(o ? { i, field: "start" } : null)
                    }
                    disabled={disabled}
                  >
                    <TimesEditor
                      p={p}
                      focus="start"
                      check={(a, b) => problem(i, a, b)}
                      onCommit={(np) => setAt(i, np)}
                    />
                  </TimeLabel>
                  {!shared && !narrow && (
                    <TimeLabel
                      m={p.end}
                      className="-translate-x-full"
                      open={edit?.i === i && edit.field === "end"}
                      onOpenChange={(o) =>
                        setEdit(o ? { i, field: "end" } : null)
                      }
                      disabled={disabled}
                    >
                      <TimesEditor
                        p={p}
                        focus="end"
                        check={(a, b) => problem(i, a, b)}
                        onCommit={(np) => setAt(i, np)}
                      />
                    </TimeLabel>
                  )}
                </React.Fragment>
              );
            })}
          </div>
        </div>
        <div className="flex items-start gap-3">
          {canAdd && <HangingAdd label="Add preferred time" onClick={add} />}
          {/* NO ROOM LEFT (Pavan, 2026-10-20) — said where the add was pressed. */}
          {full && (
            <p
              role="alert"
              className="flex items-center gap-1.5 pt-1.5 text-xs text-status-failed"
            >
              <TriangleAlert className="size-3.5 shrink-0" />
              Delete or adjust the current preferred time to add a new one.
            </p>
          )}
        </div>
      </div>
    </SheetField>
  );
}

/** A bar's time under its end — pressed, it opens the typed times. */
function TimeLabel({
  m,
  text,
  className,
  open,
  onOpenChange,
  disabled,
  children,
}: {
  m: number;
  /** In place of the one time — a short bar's "8a–9:20a". */
  text?: string;
  className?: string;
  open: boolean;
  onOpenChange: (o: boolean) => void;
  disabled?: boolean;
  children: React.ReactNode;
}) {
  const label = (
    <span
      className={cn(
        "absolute top-[59px] text-xs leading-none tabular-nums text-foreground",
        className,
      )}
      style={{ left: pct(m) }}
    >
      {text ?? short(m)}
    </span>
  );
  if (disabled) return label;
  return (
    <Popover open={open} onOpenChange={onOpenChange}>
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label={`Type the preferred time, ${short(m)}`}
          className={cn(
            "absolute top-[57px] -ml-0.5 rounded-sm px-0.5 py-0.5 text-xs leading-none tabular-nums text-foreground underline decoration-current/40 decoration-dotted underline-offset-2 outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring/50",
            className,
          )}
          style={{ left: pct(m) }}
        >
          {text ?? short(m)}
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-auto p-3">
        {children}
      </PopoverContent>
    </Popover>
  );
}

/** START AND END TO THE MINUTE — each change that fits is kept at once. */
function TimesEditor({
  p,
  focus,
  check,
  onCommit,
}: {
  p: TimeSpan;
  focus: "start" | "end";
  check: (s: number | null, e: number | null) => string | null;
  onCommit: (p: TimeSpan) => void;
}) {
  const [a, setA] = React.useState(hhmm(p.start));
  const [b, setB] = React.useState(hhmm(p.end));
  const err = check(fromHhmm(a), fromHhmm(b));
  const put = (na: string, nb: string) => {
    const s = fromHhmm(na);
    const e = fromHhmm(nb);
    if (!check(s, e)) onCommit({ start: s!, end: e! });
  };
  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-end gap-2">
        <label className="flex flex-col gap-1.5 text-xs font-medium text-muted-foreground">
          Start
          <Input
            type="time"
            step={60}
            className="w-[130px]"
            value={a}
            autoFocus={focus === "start"}
            onChange={(e) => {
              setA(e.target.value);
              put(e.target.value, b);
            }}
          />
        </label>
        <label className="flex flex-col gap-1.5 text-xs font-medium text-muted-foreground">
          End
          <Input
            type="time"
            step={60}
            className="w-[130px]"
            value={b}
            autoFocus={focus === "end"}
            onChange={(e) => {
              setB(e.target.value);
              put(a, e.target.value);
            }}
          />
        </label>
      </div>
      {err && <p className="text-xs text-status-failed">{err}</p>}
    </div>
  );
}

import * as React from "react";
import { Plus } from "lucide-react";
import { cn } from "@/lib/utils";

/*
  THE ADD ON A TABLE — a tab hanging off the card's bottom-left corner.

  WHY NOT A BAND INSIDE THE CARD. A full-width strip draws a rule across the
  whole card to carry one small act, and what it reads as is an empty extra
  row of the table. (Pavan, 2026-09-22 — after both were built and put side by
  side.)

  WHY FILLED AND NOT OUTLINED. It takes the table's own header tint, so it
  continues the table rather than sitting near it as a separate control. An
  outline would be a second box under a card that already has one, which is
  the nesting `docs/ds/ui/2-rules.md` §10f exists to remove.

  A PLUS, AND THE WORDS ON HOVER. The row it adds is one of many and the sign
  says the act; a permanent label makes an ordinary add look like the
  section's main one. The label still arrives on keyboard focus, so it is not
  a thing only a mouse can find, and the button keeps its `aria-label` either
  way — the collapsed state is a visual economy, never a nameless control.
*/

/* IT CAN OPEN A MENU (Pavan, 2026-10-07). When one add offers a choice of
   row — the quote's Fee or Tax — it is a menu's trigger, so whatever the
   trigger hands it (ref, pointer and key handlers, aria) is passed through.
   Nothing about how it looks changes. */
export function HangingAdd({
  label,
  onClick,
  disabled,
  className,
  ...trigger
}: {
  /** "Add products", "Add vendor" — the table's own noun, always plural-safe. */
  label: string;
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  disabled?: boolean;
  className?: string;
} & Omit<React.ComponentPropsWithRef<"button">, "onClick" | "className" | "disabled">) {
  const [open, setOpen] = React.useState(false);

  return (
    <button
      {...trigger}
      type="button"
      aria-label={label}
      disabled={disabled}
      onClick={onClick}
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
      onFocus={() => setOpen(true)}
      onBlur={() => setOpen(false)}
      className={cn(
        /* SQUARE ON TOP, ROUNDED BELOW — the top edge is the card's bottom
           edge, and a radius there would show a notch between them. */
        "flex h-8 items-center rounded-t-none rounded-b-md bg-fp-table-header px-2.5",
        "text-sm font-medium text-foreground outline-none transition-colors",
        "hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring/50",
        "disabled:pointer-events-none disabled:opacity-50",
        className
      )}
    >
      <Plus className="size-4 shrink-0" />
      <span
        className={cn(
          "overflow-hidden whitespace-nowrap transition-[max-width,opacity,padding] duration-200",
          open ? "max-w-[140px] pl-1.5 opacity-100" : "max-w-0 opacity-0"
        )}
      >
        {label}
      </span>
    </button>
  );
}

import type * as React from "react";

import { Slider } from "@/components/ui/slider";
import { cn } from "@/lib/utils";

/*
  A delivery window, as a range on a day.

  WHY NOT A DROPDOWN. The list held six fixed windows, and a window is not a
  category — it is two times. A customer who can take a load between 7 and 11
  had to be filed under "6:00 AM – 10:00 AM" and the two hours of difference
  lived in somebody's head. Six options also cannot say "all day", which is a
  real answer, or "a two-hour slot", which is the one that matters when a site
  has a gate that opens twice.

  THE DAY IS THE SCALE, and it is drawn: midnight to midnight with the working
  hours marked, so a window reads as a POSITION rather than as a pair of
  numbers. That is the whole argument for a slider here — you are choosing
  where in the day something sits, and a list makes you translate.

  THIRTY-MINUTE STEPS. Fuel delivery is not scheduled to the minute, and a
  slider that can land on 8:07 offers a precision the business does not have.
*/

const STEP_MIN = 30;
const DAY_MIN = 24 * 60;

/** `8:00 AM`. Midnight prints as `12:00 AM`, and 24:00 as `12:00 AM` next day. */
export function formatMinutes(total: number): string {
  const m = ((total % DAY_MIN) + DAY_MIN) % DAY_MIN;
  const h24 = Math.floor(m / 60);
  const mm = m % 60;
  const suffix = h24 < 12 ? "AM" : "PM";
  const h12 = h24 % 12 === 0 ? 12 : h24 % 12;
  return `${h12}:${String(mm).padStart(2, "0")} ${suffix}`;
}

/** `8:00 AM` back to minutes. Tolerant of the `8:00 AM – 12:00 PM` halves. */
export function parseMinutes(label: string): number | null {
  const m = label.trim().match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  if (!m) return null;
  let h = Number(m[1]) % 12;
  if (m[3].toUpperCase() === "PM") h += 12;
  return h * 60 + Number(m[2]);
}

/** `"8:00 AM – 12:00 PM"` → `[480, 720]`. Null when it does not parse. */
export function parseWindow(label: string): [number, number] | null {
  const [a, b] = label.split(/[–-]/);
  if (!a || !b) return null;
  const start = parseMinutes(a);
  const end = parseMinutes(b);
  return start === null || end === null ? null : [start, end];
}

export const formatWindow = (start: number, end: number) =>
  `${formatMinutes(start)} – ${formatMinutes(end)}`;

/** Hours worth labelling. Every sixth, so the scale reads without crowding. */
const TICKS = [0, 6, 12, 18, 24];

/** `4 hr window`, or `All day` when the pair covers midnight to midnight. */
export function formatSpan(start: number, end: number): string {
  const span = end - start;
  if (span >= DAY_MIN) return "All day";
  return `${(span / 60).toLocaleString(undefined, { maximumFractionDigits: 1 })} hr window`;
}

export interface TimeWindowSliderProps {
  /** Minutes from midnight. */
  start: number;
  end: number;
  onChange: (start: number, end: number) => void;
  /** Shortest window the slider will allow, in minutes. Default 60. */
  minSpan?: number;
  /**
   * The field's own label. Given here rather than by a wrapping `SheetField`
   * so the label and the value it produces share ONE line — see below.
   */
  label?: React.ReactNode;
  /** Marks the label with the destructive asterisk the DS forms already use. */
  required?: boolean;
  /** Read-only — a record past the point where its schedule can move. */
  disabled?: boolean;
  className?: string;
  "aria-label"?: string;
}

export function TimeWindowSlider({
  start,
  end,
  onChange,
  minSpan = 60,
  label,
  required,
  disabled,
  className,
  "aria-label": ariaLabel = "Delivery window",
}: TimeWindowSliderProps) {
  return (
    /*
      ONE FIELD, ONE HEIGHT. The label, the value and the track used to sit on
      three lines, which made this field taller than the date beside it and
      broke the row: two controls that are answered together should finish
      together. Label and value now share the label's line, and the track and
      its scale fill exactly the 36px a control occupies — so the field is the
      same height as any other, and the row's baselines line up.
    */
    <div className={cn("flex flex-col gap-1.5", className)}>
      {/* THE VALUE IS READ, not inferred from where the handles sit. A slider
          whose value can only be estimated is one people distrust for anything
          precise — so it is printed, next to the name of the thing it sets. */}
      {/* THE WINDOW NEVER TRUNCATES (2026-10-15 — sheets now fit their
          content, so a half-width field is ~280px). The span note is the one
          that gives way: it truncates first. */}
      <div className="flex min-w-0 items-baseline justify-between gap-3">
        <span className="flex shrink-0 items-baseline gap-2">
          {label && (
            <span className="text-sm font-medium whitespace-nowrap text-foreground">
              {label}
              {required && <span className="text-destructive"> *</span>}
            </span>
          )}
          <span className="text-sm whitespace-nowrap tabular-nums text-foreground">
            {formatWindow(start, end)}
          </span>
        </span>
        <span className="min-w-0 truncate text-xs text-muted-foreground">
          {formatSpan(start, end)}
        </span>
      </div>

      {/*
        THE CONTROL ZONE IS THE INPUT'S OWN 36px, and the two parts are placed
        inside it rather than stacked to fill it. The scale is pinned to the
        floor, so its baseline is the input's bottom edge.

        THE TRACK IS CENTRED BETWEEN THE TWO LINES OF TEXT, not in the box.
        Centring it in the box put 21px of air above it and 7px below, so the
        value on top read as belonging to nothing and the scale looked stuck to
        the track. It now sits halfway between the bottom of the value and the
        top of the scale — 12px of air either side — which is what makes the
        three lines read as one control.
      */}
      <div className="relative h-9">
        <Slider
          className="absolute inset-x-0 top-1.5"
          aria-label={ariaLabel}
          min={0}
          max={DAY_MIN}
          step={STEP_MIN}
          minStepsBetweenThumbs={minSpan / STEP_MIN}
          value={[start, end]}
          disabled={disabled}
          onValueChange={([a, b]) => onChange(a, b)}
        />

        {/* THE SCALE, so the handles have something to mean. Without it the
            track is a bare line and "where in the day is this" is unanswerable
            without reading the numbers above.

            THE END LABELS ARE NOT CENTRED. Midnight sits at 0% and at 100%, so
            centring hung half of each one outside the field — the left edge of
            the form stepped out and back for one label. They are pinned to the
            edges instead, which is also where the track starts and stops. */}
        <div
          aria-hidden
          className="absolute inset-x-0 bottom-0 h-3 leading-none select-none"
        >
          {TICKS.map((h, i) => {
            const first = i === 0;
            const last = i === TICKS.length - 1;
            return (
              <span
                key={h}
                className={cn(
                  "absolute bottom-0 text-[11px] leading-none tabular-nums text-muted-foreground",
                  first && "left-0",
                  last && "right-0",
                  !first && !last && "-translate-x-1/2"
                )}
                style={first || last ? undefined : { left: `${(h / 24) * 100}%` }}
              >
                {h === 0 || h === 24 ? "12a" : h === 12 ? "12p" : h < 12 ? `${h}a` : `${h - 12}p`}
              </span>
            );
          })}
        </div>
      </div>
    </div>
  );
}

import * as React from "react";

/* The shared state behind `form-steps.tsx`, kept apart so that file exports only components. */

/** True inside a stepped sheet's form. */
export const FormStepsContext = React.createContext(false);
/** True inside a step, so the sections in it do not become steps too. */
export const InsideFormStepContext = React.createContext(false);

/** The attributes that make an element a step the list can find. */
export function formStepAttrs(label: string) {
  return { "data-form-step": label };
}

/**
 * The classes a step's own element takes: room for the landing blink's fill,
 * pulled back out so the fields stay where they were.
 */
export const FORM_STEP_CLASS = "-m-3 rounded-lg p-3";

import * as React from "react";
import { CircleAlert, Info, Minus } from "lucide-react";
import { cn } from "@/lib/utils";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Steps, type StepItem } from "@/components/ui/steps";
import {
  FORM_STEP_CLASS,
  FormStepsContext,
  InsideFormStepContext,
  formStepAttrs,
} from "./form-steps-context";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

/* Shared building blocks for the Side Sheet variants (Figma 27610:58293). */

/** Section = muted group heading + fields. */
export function SheetSection({
  title,
  action,
  note,
  variant: variantProp = "card",
  flush = false,
  hanging,
  bodyClassName,
  headingClassName,
  children,
  className,
  id,
}: {
  title: string;
  /**
   * `card` — the default — draws the section as a bordered block with its
   * title in a tinted header band. A sheet is a stack of questions about
   * different things, and gaps alone were carrying the whole job of saying
   * where one subject ended and the next began; at 40px they did it only for
   * as long as nothing in a section grew. The border says it at any length.
   *
   * `plain` is the old heading-over-fields form, for the handful of places
   * that are a single continuous list rather than a set of groups.
   */
  variant?: "plain" | "card" | "outline";
  /**
   * Classes for the heading text — for a form that sets its group headings at
   * a different step of the type scale.
   */
  headingClassName?: string;
  /**
   * Card variant only: drop the body's padding so a single child can run edge
   * to edge under the header band.
   *
   * FOR A SECTION THAT IS ONE TABLE. A table already draws a border, a header
   * band and a rule between every row; set inside a padded card it became a
   * box in a box, with 16px of nothing between two lines doing the same job
   * and the table's own header band sitting a hair inside the card's. Flush,
   * the card's border IS the table's border and there is one edge instead of
   * two. The child owns its own insets — anything that is not the table (an
   * Add row, a footnote) has to bring its own padding and its own top rule.
   */
  flush?: boolean;
  /**
   * A control that HANGS OFF THE CARD'S BOTTOM-LEFT, outside it.
   *
   * FOR THE ADD ON A TABLE. The card's bottom-left corner squares so the two
   * join, and the control continues the table's last row rather than sitting
   * on a full-width band inside the card — a band draws a rule across the
   * whole card to carry one small act, and reads as an empty extra row of the
   * table. (Pavan, 2026-09-22.)
   */
  hanging?: React.ReactNode;
  /**
   * Classes for the BODY, not the card — for a section that has to fill the
   * height it is given rather than wrap its content. A composer's message box
   * is the case: it should run to the bottom of the sheet, and only the body
   * can be told to grow.
   */
  bodyClassName?: string;
  /**
   * Controls that act on the SECTION rather than on one field — "Add asset",
   * "Refresh". They sit on the heading row, right-aligned, because a control
   * that owns a whole section has no field to belong to.
   */
  action?: React.ReactNode;
  /** An explainer beside the heading — typically `SheetSectionNote`. */
  note?: React.ReactNode;
  children: React.ReactNode;
  className?: string;
  /**
   * An anchor on the section, for a caller that has to bring one section into
   * view — a list's footer action that opens a record AT the part it is about.
   */
  id?: string;
}) {
  /* SECTION RHYTHM — 40 / 16. The gap between sections is 40px (owned by the
     sheet body); the gap between a section's title and its content is 16px. The
     outer gap being 2.5x the inner is what makes a heading read as belonging to
     the block beneath it rather than floating between two blocks. At 20 the
     title sat almost equidistant from both; below 16 it welds to the first
     field and the whole boundary rests on the 40.

     THE 16 IS MEASURED FROM THE TITLE, and that is the whole reason the heading
     row has no height of its own. It used to be `min-h-7` (28px) around a 20px
     line, and `items-center` split the spare 8px evenly — so what anyone could
     actually see between the words and the content was 20px, and 22px in a
     section whose heading also carried a 32px action button. The rule said 16
     and the screen said 20: the row was padding itself and calling it rhythm.

     An ACTION taller than the title now hangs off the line instead of pushing
     the content down: its wrapper is fixed at the title's own 20px and centres
     a taller child, which overflows the box without growing it. That holds for
     any control put there — a 32px button, a switch, a picker — so the 16
     cannot drift again the next time a section gains an action. */
  /* IN A STEPPED FORM (see `form-steps`) the card's band goes: a section
     that is fields becomes `plain`, a section that is a table keeps its rim as
     `outline`. A top-level section is also a step, named by its title. */
  const stepped = React.useContext(FormStepsContext);
  const insideStep = React.useContext(InsideFormStepContext);
  const isStep = stepped && !insideStep;
  const variant =
    stepped && variantProp === "card"
      ? flush || hanging
        ? "outline"
        : "plain"
      : variantProp;
  const stepAttrs = isStep ? formStepAttrs(title) : {};
  if (isStep) {
    children = (
      <InsideFormStepContext.Provider value>{children}</InsideFormStepContext.Provider>
    );
  }

  const heading = (
    <div className="flex items-center justify-between gap-4">
      <div className="flex items-center gap-1.5">
        <h3
          className={cn(
            "text-sm font-semibold text-muted-foreground",
            /* Sub-heading size, dimmed so the fields lead. */
            stepped && "text-base font-medium",
            headingClassName
          )}
        >
          {title}
        </h3>
        {/* Sits WITH the heading, not after the content: an explanation of
            how a section works belongs where the section is named, and on
            demand rather than as a paragraph everyone reads once. */}
        {note}
      </div>
      {action && (
        <div className="flex h-5 shrink-0 items-center justify-end">{action}</div>
      )}
    </div>
  );

  if (variant === "outline") {
    /* `outline` — the plain heading OVER an outlined box, no band. For a form
       whose group headings carry no fill but whose tables keep their rim.
       The box takes `flush` and `hanging` exactly as the card does. The rim
       is the data table's `--border`, per the DS table stroke. */
    const box = (
      <div
        className={cn(
          "flex shrink-0 flex-col overflow-hidden rounded-lg border border-border",
          !flush && "gap-4 p-4",
          hanging && "rounded-bl-none",
          bodyClassName
        )}
      >
        {children}
      </div>
    );
    return (
      <section
        id={id}
        {...stepAttrs}
        className={cn("flex shrink-0 flex-col gap-4", isStep && FORM_STEP_CLASS, className)}
      >
        {heading}
        {hanging ? (
          <div className="flex flex-col">
            {box}
            <div className="flex w-full items-center justify-between gap-4">
              {hanging}
            </div>
          </div>
        ) : (
          box
        )}
      </section>
    );
  }

  if (variant === "card") {
    /* THE HEADING MOVES INTO A BAND, because a title inside a bordered block
       that shares the block's fill reads as the first row of content rather
       than as the name of what follows.

       The 16px title→content rhythm the plain variant measures so carefully is
       not needed here: the band's own edge is the separation, and it holds at
       any section length — which is the thing a 40px gap could not do. */
    const card = (
      <section
        id={hanging ? undefined : id}
        /* `shrink-0` IS LOAD-BEARING, not tidiness. The sheet body is a flex
           column, and `overflow-hidden` switches a flex item's automatic
           minimum size from its content to zero — so without this the whole
           card collapses to its own 2px of border. */
        className={cn(
          /* THE RIM IS `--fp-outline-1`, NOT `--border` (Pavan, 2026-09-22).
             The DS's stroke table has said so all along — outline-1 is "a
             card's own rim" and `--border` is "a structural divider" — and
             this card was drawing the divider weight round its outside, which
             is why a card sat heavier on the page than the lines inside it.
             In DARK the two tokens carry the same value, so this is a
             light-mode correction only. */
          "shrink-0 overflow-hidden rounded-lg border border-fp-outline-1",
          /* SQUARED WHERE THE HANGING CONTROL JOINS, so the two read as one
             shape rather than a rounded box with a tab floating under it. */
          hanging && "rounded-bl-none",
          /* THE CALLER'S CLASSES GO ON WHICHEVER ELEMENT IS THE OUTER ONE.
             With something hanging, that is the wrapper below, not this —
             `lg:col-span-3` landing here put the SECTION inside a grid item
             that was still one column wide, so a section could be told to take
             three columns and silently take one. (Found 2026-09-22, on the
             Documents table.) */
          !hanging && className
        )}
      >
        <div className="border-b border-border bg-fp-surface-1a px-4 py-2.5">
          {heading}
        </div>
        <div
          className={cn(
            "flex flex-col",
            !flush && "gap-4 p-4",
            bodyClassName
          )}
        >
          {children}
        </div>
      </section>
    );

    /* THE WRAPPER OWNS THE `shrink-0` AND THE ID once there is something
       hanging: the card and its tab are one block in the sheet's stack, and
       the body's 40px gap has to fall after the tab rather than between the
       two. */
    return hanging ? (
      <div id={id} className={cn("flex shrink-0 flex-col", className)}>
        {card}
        {/* THE HANGING ROW runs the card's width so a second thing can sit at
            its right end — the add on the left, a flag about the whole unit on
            the right. With one child `justify-between` leaves it on the left,
            which is where a lone add belongs. */}
        <div className="flex w-full items-center justify-between gap-4">
          {hanging}
        </div>
      </div>
    ) : (
      card
    );
  }

  return (
    <section
      id={id}
      {...stepAttrs}
      className={cn("flex flex-col gap-4", isStep && FORM_STEP_CLASS, className)}
    >
      {heading}
      {children}
    </section>
  );
}

/**
 * The card's own insets, given back to one child of a `flush` section.
 *
 * A flush section is for a table, and a section is rarely ONLY a table — a
 * banner above it, a switch below. Those still need the 16px the body gave up,
 * and they need it individually rather than as a blanket, because the table
 * between them must keep running to the card's edge. Add `border-t`/`border-b`
 * at the call site where the inset meets the table: the rule belongs to the
 * boundary, and only the call site knows which side it is on.
 */
export function SheetSectionInset({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <div className={cn("flex flex-col gap-4 p-4", className)}>{children}</div>
  );
}

/**
 * The remove control for an OPTIONAL section — the one that takes a section
 * that has been turned on back to its "Add …" box.
 *
 * A MINUS, NOT A BIN. A bin says a record is about to be destroyed, and this
 * destroys nothing: the section collapses to the CTA it came from and can be
 * added again in one click. The two icons look alike at 16px and mean opposite
 * things about whether the click can be taken back, so the optional-section
 * control never wears the bin — that stays on the ROW delete inside a table,
 * where a row really does go.
 *
 * QUIET UNTIL REACHED FOR. Emptying a section that was optional in the first
 * place should not compete with the table for attention, so it is a muted icon
 * that comes to full contrast and slides its label out on hover or focus. The
 * label is what makes it safe — a bare glyph beside a table of rows reads as
 * though it might remove a row.
 *
 * IT ASKS ONLY WHEN THERE IS SOMETHING TO LOSE. `hasContent` is the caller's
 * answer to "has anyone typed anything in here yet" — with rows filled the
 * click opens a confirm, and on an untouched section it just closes it. A
 * dialog over an empty table teaches people to dismiss dialogs without reading
 * them, which is exactly the habit that makes the one that matters useless.
 */
export function SheetSectionRemove({
  label,
  hasContent,
  onClick,
}: {
  /** Names what goes, e.g. "Remove peripherals". Shown on hover and to AT. */
  label: string;
  /**
   * True when the section holds something a person put there. Only then is
   * removal worth confirming — the caller knows what "filled in" means for its
   * own rows, so it decides rather than this component guessing.
   */
  hasContent?: boolean;
  onClick: () => void;
}) {
  const trigger = (
    <button
      type="button"
      onClick={hasContent ? undefined : onClick}
      aria-label={label}
      className="group/rm flex h-8 items-center gap-1.5 rounded-md px-2 text-muted-foreground outline-none transition-colors hover:bg-accent hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
    >
      <Minus className="size-4 shrink-0" />
      <span className="max-w-0 overflow-hidden text-sm whitespace-nowrap opacity-0 transition-[max-width,opacity] duration-200 group-hover/rm:max-w-40 group-hover/rm:opacity-100 group-focus-visible/rm:max-w-40 group-focus-visible/rm:opacity-100">
        {label}
      </span>
    </button>
  );

  if (!hasContent) return trigger;

  return (
    <AlertDialog>
      <AlertDialogTrigger asChild>{trigger}</AlertDialogTrigger>
      <AlertDialogContent>
        <AlertDialogHeader>
          {/* The button's own label, as a question — the dialog answers the
              click that opened it rather than restating the section's name. */}
          <AlertDialogTitle>{label}?</AlertDialogTitle>
          <AlertDialogDescription>
            Everything added here will be erased. This cannot be undone.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>Cancel</AlertDialogCancel>
          <AlertDialogAction variant="destructive" onClick={onClick}>
            Remove
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

/** Field = label + control + helper text. */
export function SheetField({
  label,
  description,
  required,
  children,
  className,
}: {
  /**
   * A node, not just a string: a field's label row sometimes carries a control
   * that acts on the whole field — an "Invite" beside a picker — and that
   * control belongs on the label row rather than trailing the field's body.
   */
  label?: React.ReactNode;
  description?: string;
  /** Marks the label with the destructive asterisk the DS forms already use. */
  required?: boolean;
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <div className={cn("flex flex-col gap-1.5", className)}>
      {label && (
        <label className="block text-sm font-medium text-foreground">
          {label}
          {required && <span className="text-destructive"> *</span>}
        </label>
      )}
      {/* HELPER TEXT IS PART OF THE CONTROL, 4px under it — not the next thing
          down the form. At the field gap it floats between two controls and gets
          read as a label for the one below. Label→control keeps the field's own
          rhythm; control→helper is always 4px. */}
      <div className="flex flex-col gap-1">
        {children}
        {description && (
          <p className="text-xs text-muted-foreground">{description}</p>
        )}
      </div>
    </div>
  );
}

/** The top-of-body alert banner shared by every variant. */
export function InfoAlert() {
  return (
    <Alert>
      <CircleAlert />
      <AlertTitle>Alert Title</AlertTitle>
      <AlertDescription>This is an alert description.</AlertDescription>
    </Alert>
  );
}

/**
 * The "why does this section behave this way" explainer, on demand.
 *
 * A paragraph under a section is read once and then permanently in the way; the
 * rule it states is needed at the moment someone WONDERS, which is rarely the
 * moment they first arrive. On CLICK rather than hover, because hover cannot be
 * reached by touch and a tooltip that appears while you are aiming at something
 * else is worse than no tooltip.
 *
 * Deliberately NARROW. Explanations set to the full width of a sheet become one
 * long line that has to be tracked back across; a few short lines are read at a
 * glance.
 */
export function SheetSectionNote({
  label = "About this section",
  children,
}: {
  /** Names the button for assistive tech. */
  label?: string;
  children: React.ReactNode;
}) {
  return (
    <Popover>
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label={label}
          className="flex size-5 items-center justify-center rounded-full text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50 data-[state=open]:text-foreground"
        >
          <Info className="size-4" />
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-64 text-xs leading-relaxed">
        {children}
      </PopoverContent>
    </Popover>
  );
}

/**
 * The sheet's step strip — the DS `Steps` control, sized and spaced for a
 * sheet header.
 *
 * A THIN WRAPPER ON PURPOSE. It exists so a sheet does not have to remember the
 * height and the border the header strip needs, not to be a second stepper: the
 * states, the numbering, the connector and the disabled-with-a-reason behaviour
 * are all `Steps`.
 */
export function SheetSteps({
  steps,
  value,
  onValueChange,
  tone,
  variant,
}: {
  steps: StepItem[];
  value: string;
  onValueChange: (next: string) => void;
  tone?: "brand" | "accent" | "neutral";
  variant?: "track" | "rings";
}) {
  return (
    <Steps
      tone={tone}
      variant={variant}
      steps={steps}
      value={value}
      onValueChange={onValueChange}
      className="my-2.5"
    />
  );
}

import * as React from "react";
